[sink_function_007aa7a7dd9778e91b28.c:124]         break;
[sink_function_007aa7a7dd9778e91b28.c:125]       }
[sink_function_007aa7a7dd9778e91b28.c:126]       case JPEGCompression:
[sink_function_007aa7a7dd9778e91b28.c:127]       {
[sink_function_007aa7a7dd9778e91b28.c:128]         (void) SetImageStorageClass(image,DirectClass);
